"use client";

import React, { useState } from "react";
import { Calendar as CalendarIcon, ChevronDown } from "lucide-react";

interface DateRangeFilterProps {
  onDateChange: (range: { startDate: string; endDate: string; label: string }) => void;
}

const PRESET_RANGES = [
  { label: "Today", days: 1 },
  { label: "Last 7 Days", days: 7 },
  { label: "Last 30 Days", days: 30 },
  { label: "This Month", days: 30 },
];

export const DateRangeFilter: React.FC<DateRangeFilterProps> = ({ onDateChange }) => {
  const [selectedLabel, setSelectedLabel] = useState<string>("Last 7 Days");
  const [isOpen, setIsOpen] = useState(false);
  const [customStart, setCustomStart] = useState("2026-11-11");
  const [customEnd, setCustomEnd] = useState("2026-11-18");

  const handleSelectPreset = (preset: { label: string; days: number }) => {
    setSelectedLabel(preset.label);
    const end = new Date();
    const start = new Date();
    start.setDate(end.getDate() - preset.days);

    const startStr = start.toISOString().split("T")[0];
    const endStr = end.toISOString().split("T")[0];

    setCustomStart(startStr);
    setCustomEnd(endStr);
    onDateChange({ startDate: startStr, endDate: endStr, label: preset.label });
    setIsOpen(false);
  };

  const handleCustomApply = () => {
    setSelectedLabel("Custom Range");
    onDateChange({ startDate: customStart, endDate: customEnd, label: "Custom Range" });
    setIsOpen(false);
  };

  return (
    <div className="relative inline-block text-left">
      <div className="flex items-center gap-3">
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="flex items-center gap-2.5 px-4 py-2.5 bg-slate-800/80 hover:bg-slate-700/80 text-slate-200 border border-slate-700 rounded-xl shadow-sm transition-all text-sm font-medium focus:ring-2 focus:ring-indigo-500/20"
        >
          <CalendarIcon className="w-4 h-4 text-indigo-400" />
          <span>{selectedLabel}</span>
          <span className="text-xs text-slate-400 font-normal">
            ({customStart} ~ {customEnd})
          </span>
          <ChevronDown className="w-4 h-4 text-slate-400 ml-1" />
        </button>
      </div>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-80 rounded-2xl bg-slate-800 border border-slate-700 shadow-2xl p-4 z-50 animate-in fade-in zoom-in-95 duration-150">
          <div className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">
            Preset Ranges
          </div>
          <div className="grid grid-cols-2 gap-2 mb-4">
            {PRESET_RANGES.map((preset) => (
              <button
                key={preset.label}
                onClick={() => handleSelectPreset(preset)}
                className={`px-3 py-2 text-xs font-medium rounded-lg transition-all text-left ${
                  selectedLabel === preset.label
                    ? "bg-indigo-600 text-white shadow-lg shadow-indigo-600/30"
                    : "bg-slate-700/50 hover:bg-slate-700 text-slate-300"
                }`}
              >
                {preset.label}
              </button>
            ))}
          </div>

          <div className="border-t border-slate-700/60 pt-3">
            <div className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">
              Custom Date
            </div>
            <div className="space-y-2">
              <div>
                <label className="text-[11px] text-slate-400 block mb-1">Start Date</label>
                <input
                  type="date"
                  value={customStart}
                  onChange={(e) => setCustomStart(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-slate-200 focus:outline-none focus:border-indigo-500"
                />
              </div>
              <div>
                <label className="text-[11px] text-slate-400 block mb-1">End Date</label>
                <input
                  type="date"
                  value={customEnd}
                  onChange={(e) => setCustomEnd(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs text-slate-200 focus:outline-none focus:border-indigo-500"
                />
              </div>
              <button
                onClick={handleCustomApply}
                className="w-full mt-2 bg-indigo-600 hover:bg-indigo-500 text-white font-medium py-1.5 rounded-lg text-xs transition-colors shadow-md shadow-indigo-600/20"
              >
                Apply Range
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
